-- Independently generated ZIP fixtures for all three RFC 1951 block types.
local function dynamicPayload()
    local tBytes = {};
    for nValue = 0, 255 do tBytes[#tBytes + 1] = string.char(nValue); end
    return string.rep(table.concat(tBytes), 16)..string.rep("dynamic Huffman repeat ", 1000);
end
return {
    {Block = 0, Archive = "", Payload = string.rep("stored deflate\0\255", 20)},
    {Block = 1, Archive = "", Payload = string.rep("fixed Huffman abc ", 100)},
    {Block = 2, Archive = "", Payload = dynamicPayload()},
};
